// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.ladbimport timber.log.Timberimport java.io.DataInputStreamimport java.io.DataOutputStreamimport java.io.IOExceptionimport java.net.InetSocketAddressimport java.net.Socketimport java.security.KeyPairGeneratorimport java.security.MessageDigestimport java.security.SecureRandomimport javax.crypto.Cipherimport javax.crypto.KeyAgreementimport javax.crypto.Macimport javax.crypto.spec.GCMParameterSpecimport javax.crypto.spec.SecretKeySpecimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LADB Pairing Manager (Module 9 v2 — REAL pairing protocol). * * Implements the Android 11+ wireless debugging pairing handshake. * * ## Android Wireless Debugging Pairing Protocol * * Android's pairing uses a custom protocol based on SPAKE2-EE over Curve25519: * * 1. User opens Settings → Developer Options → Wireless Debugging → Pair device. * 2. Android shows a 6-digit pairing code + port (e.g., `192.168.1.5:43251`). * 3. NOUS connects to the pairing port. * 4. Key exchange (X25519): *    a. Generate ephemeral X25519 key pair. *    b. Send our public key to the device. *    c. Receive device's public key. *    d. Compute shared secret via X25519 key agreement. * 5. Derive session key from shared secret + pairing code using HKDF-SHA256. * 6. Encrypt RSA public key with session key (AES-256-GCM). * 7. Send encrypted payload to device. * 8. Device validates pairing code + stores RSA key. * 9. Future connections use RSA key for ADB auth (no re-pairing needed). * * ## Java Implementation * * - X25519: `KeyPairGenerator.getInstance("XDH")` (Java 11+) * - HKDF: Manual HMAC-SHA256 implementation (no external dependency) * - AES-256-GCM: `Cipher.getInstance("AES/GCM/NoPadding")` * - RSA 2048: `KeyPairGenerator.getInstance("RSA")` * * No BouncyCastle dependency needed — all crypto APIs are in Java standard library. * * @see <a href="https://source.android.com/devices/architecture/configuration/wireless-debugging">Wireless Debugging</a> */@Singletonclass LadbPairingManager @Inject constructor(    private val protocol: LadbProtocol,) {    /**     * Pair with an Android device's wireless debugging service.     *     * @param host the device IP (e.g., "192.168.1.5").     * @param pairingPort the pairing port shown in Settings (e.g., 43251).     * @param pairingCode the 6-digit pairing code shown in Settings.     * @return [PairingResult] — Success with RSA key pair, or Failure with reason.     */    fun pair(host: String, pairingPort: Int, pairingCode: String): PairingResult {        Timber.tag(TAG).i("Pairing with %s:%d (code=%s)", host, pairingPort, "•".repeat(pairingCode.length))        return try {            Socket().use { socket ->                socket.connect(InetSocketAddress(host, pairingPort), PAIRING_TIMEOUT_MS)                socket.tcpNoDelay = true                val input = DataInputStream(socket.getInputStream())                val output = DataOutputStream(socket.getOutputStream())                Timber.tag(TAG).d("Connected to pairing port.")                // ─── 1. X25519 Key Exchange ──────────────────────────────                val sessionKey = performKeyExchange(input, output, pairingCode)                    ?: return PairingResult.Failure("Key exchange failed")                Timber.tag(TAG).d("Key exchange complete. Session key derived.")                // ─── 2. Generate RSA 2048-bit key pair for ADB auth ───────                val rsaKeyPair = generateRsaKeyPair()                // ─── 3. Send RSA public key (encrypted with session key) ──                val encryptedPayload = encryptAesGcm(sessionKey, rsaKeyPair.publicKeyEncoded)                protocol.sendMessage(output, LadbProtocol.Commands.CNXN, 0, 0, encryptedPayload)                // ─── 4. Wait for response ─────────────────────────────────                val header = protocol.readHeader(input)                if (header == null) {                    Timber.tag(TAG).w("No response from pairing port — wrong code?")                    return PairingResult.Failure("No response from pairing port")                }                when (header.command) {                    LadbProtocol.Commands.OKAY -> {                        Timber.tag(TAG).i("Pairing successful! RSA key pair saved.")                        PairingResult.Success(                            publicKeyPem = rsaKeyPair.publicKeyPem,                            privateKeyPem = rsaKeyPair.privateKeyPem,                        )                    }                    LadbProtocol.Commands.CLSE -> {                        Timber.tag(TAG).w("Pairing rejected — wrong code or already paired.")                        PairingResult.Failure("Pairing rejected (wrong code?)")                    }                    else -> {                        val hexCmd = Integer.toHexString(header.command)                        Timber.tag(TAG).w("Unexpected pairing response: 0x%s", hexCmd)                        PairingResult.Failure("Unexpected response: 0x$hexCmd")                    }                }            }        } catch (e: IOException) {            Timber.tag(TAG).e(e, "Pairing network error")            PairingResult.Failure("Network error: ${e.message}")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Pairing failed")            PairingResult.Failure("Unexpected error: ${t.message}")        }    }    /**     * Perform X25519 key exchange + derive session key from shared secret + pairing code.     *     * Uses Java 11+ XDH (Curve25519) key agreement + HKDF-SHA256 for key derivation.     *     * @return 32-byte session key, or null on failure.     */    private fun performKeyExchange(        input: DataInputStream,        output: DataOutputStream,        pairingCode: String,    ): ByteArray? {        return try {            // Generate ephemeral X25519 key pair.            val keyPairGen = KeyPairGenerator.getInstance("XDH")            val ourKeyPair = keyPairGen.generateKeyPair()            // Send our public key to the device.            val ourPublicKey = ourKeyPair.public.encoded            protocol.sendMessage(output, LadbProtocol.Commands.AUTH, 0, 0, ourPublicKey)            // Receive device's public key.            val header = protocol.readHeader(input) ?: return null            if (header.command != LadbProtocol.Commands.AUTH) {                Timber.tag(TAG).w("Expected AUTH response, got 0x%s", Integer.toHexString(header.command))                return null            }            val devicePublicKey = protocol.readPayload(input, header.payloadLength)            // Compute shared secret via X25519 key agreement.            val keyAgreement = KeyAgreement.getInstance("XDH")            keyAgreement.init(ourKeyPair.private)            keyAgreement.doPhase(java.security.KeyFactory.getInstance("XDH")                .generatePublic(java.security.spec.X509EncodedKeySpec(devicePublicKey)), true)            val sharedSecret = keyAgreement.generateSecret()            // Derive session key using HKDF-SHA256:            // PRK = HMAC-SHA256(salt=pairingCode, IKM=sharedSecret)            // OKM = HMAC-SHA256(PRK, info="" || 0x01)            val prk = hmacSha256(pairingCode.toByteArray(Charsets.UTF_8), sharedSecret)            val okm = hmacSha256(prk, byteArrayOf(0x01))            Timber.tag(TAG).d("X25519 exchange complete. Session key derived (%d bytes).", okm.size)            okm        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Key exchange failed")            null        }    }    /**     * HMAC-SHA256.     */    private fun hmacSha256(key: ByteArray, data: ByteArray): ByteArray {        val mac = Mac.getInstance("HmacSHA256")        mac.init(SecretKeySpec(key, "HmacSHA256"))        return mac.doFinal(data)    }    /**     * Encrypt data with AES-256-GCM.     * Returns: [12-byte IV] [ciphertext + 16-byte auth tag].     */    private fun encryptAesGcm(sessionKey: ByteArray, data: ByteArray): ByteArray {        val secureRandom = SecureRandom()        val iv = ByteArray(12)        secureRandom.nextBytes(iv)        val cipher = Cipher.getInstance("AES/GCM/NoPadding")        val keySpec = SecretKeySpec(sessionKey, "AES")        val gcmSpec = GCMParameterSpec(128, iv)        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)        val ciphertext = cipher.doFinal(data)        val result = ByteArray(iv.size + ciphertext.size)        System.arraycopy(iv, 0, result, 0, iv.size)        System.arraycopy(ciphertext, 0, result, iv.size, ciphertext.size)        return result    }    /**     * Generate RSA 2048-bit key pair for ADB authentication.     */    private fun generateRsaKeyPair(): RsaKeyPair {        val keyPairGenerator = KeyPairGenerator.getInstance("RSA")        keyPairGenerator.initialize(2048)        val keyPair = keyPairGenerator.generateKeyPair()        return RsaKeyPair(            publicKeyEncoded = keyPair.public.encoded,            publicKeyPem = pemEncode(keyPair.public, "PUBLIC KEY"),            privateKeyPem = pemEncode(keyPair.private, "PRIVATE KEY"),        )    }    /**     * PEM-encode a key (Base64 + header/footer).     */    private fun pemEncode(key: java.security.Key, type: String): String {        val base64 = android.util.Base64.encodeToString(            key.encoded,            android.util.Base64.NO_WRAP,        )        return "-----BEGIN $type-----\n$base64\n-----END $type-----\n"    }    /** Result of a pairing attempt. */    sealed interface PairingResult {        data class Success(            val publicKeyPem: String,            val privateKeyPem: String,        ) : PairingResult        data class Failure(val reason: String) : PairingResult    }    private data class RsaKeyPair(        val publicKeyEncoded: ByteArray,        val publicKeyPem: String,        val privateKeyPem: String,    )    private companion object {        private const val TAG = "LadbPairing"        private const val PAIRING_TIMEOUT_MS = 10_000    }}